#include <stdio.h>
#include <stdlib.h>

static char inbuf[1 << 20];
static int inpos = 0, inlen = 0;

static inline char getch(void) {
    if (inpos >= inlen) {
        inlen = (int)fread(inbuf, 1, sizeof(inbuf), stdin);
        inpos = 0;
        if (inlen <= 0) return 0;
    }
    return inbuf[inpos++];
}

static int readInt(void) {
    char c = getch();
    while (c <= ' ' && c) c = getch();
    int x = 0;
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getch();
    }
    return x;
}

static char readOp(void) {
    char c = getch();
    while (c <= ' ' && c) c = getch();
    return c;
}

static char outbuf[1 << 20];
static int outpos = 0;

static inline void writeChar(char c) {
    if (outpos == (int)sizeof(outbuf)) {
        fwrite(outbuf, 1, outpos, stdout);
        outpos = 0;
    }
    outbuf[outpos++] = c;
}

static void writeInt(int x) {
    char s[12];
    int n = 0;
    if (x == 0) {
        s[n++] = '0';
    } else {
        while (x > 0) {
            s[n++] = (char)('0' + x % 10);
            x /= 10;
        }
    }
    for (int i = n - 1; i >= 0; i--) {
        writeChar(s[i]);
    }
}

int main(void) {
    int N = readInt();
    int M = readInt();
    int P = readInt();

    int *row = (int *)malloc((N + 1) * sizeof(int));
    int *col = (int *)malloc((M + 1) * sizeof(int));

    for (int i = 1; i <= N; i++) row[i] = i;
    for (int j = 1; j <= M; j++) col[j] = j;

    for (int k = 0; k < P; k++) {
        char op = readOp();
        int a = readInt();
        int b = readInt();

        if (op == 'L') {
            int tmp = row[a];
            row[a] = row[b];
            row[b] = tmp;
        } else {
            int tmp = col[a];
            col[a] = col[b];
            col[b] = tmp;
        }
    }

    for (int i = 1; i <= N; i++) {
        int base = (row[i] - 1) * M;
        for (int j = 1; j <= M; j++) {
            if (j > 1) writeChar(' ');
            writeInt(base + col[j]);
        }
        writeChar('\n');
    }

    if (outpos > 0) {
        fwrite(outbuf, 1, outpos, stdout);
    }

    free(row);
    free(col);
    return 0;
}
